function summarize(node, depth) {
  const pad = '  '.repeat(depth);
  let info = `${pad}${node.type} "${node.name}" ${Math.round(node.width)}x${Math.round(node.height)}`;
  if ('fills' in node && Array.isArray(node.fills)) {
    const fills = node.fills.filter(f => f.visible !== false).map(f => f.type === 'SOLID' ? `S(${JSON.stringify(f.color)})` : f.type).join(',');
    if (fills) info += ` fills=[${fills}]`;
  }
  if ('strokes' in node && Array.isArray(node.strokes) && node.strokes.length) {
    const strokes = node.strokes.filter(f => f.visible !== false).map(f => f.type === 'SOLID' ? `S(${JSON.stringify(f.color)})` : f.type).join(',');
    info += ` strokes=[${strokes}] strokeWeight=${node.strokeWeight}`;
  }
  if (node.type === 'TEXT') {
    info += ` chars="${node.characters}" size=${node.fontSize} font=${JSON.stringify(node.fontName)}`;
    if (Array.isArray(node.fills)) {
      const fills = node.fills.filter(f => f.visible !== false).map(f => f.type === 'SOLID' ? `S(${JSON.stringify(f.color)})` : f.type).join(',');
      info += ` tFills=[${fills}]`;
    }
  }
  if ('cornerRadius' in node) info += ` r=${node.cornerRadius}`;
  if ('effects' in node && node.effects.length) info += ` fx=${JSON.stringify(node.effects)}`;
  let result = info + '\n';
  if ('children' in node) {
    for (const c of node.children) result += summarize(c, depth + 1);
  }
  return result;
}
return summarize(button, 0) + '\n---\n' + summarize(textField, 0);

